INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'hotel_name', 'Hotel Mayfair');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'open_year', '2006');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'room_count', '198');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'hotel_address', 'Colbjørnsensgade 8, Vesterbro/Kongens Enghave, 1652 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'description', 'Tọa lạc tại trung tâm Copenhagen, Hotel Mayfair, cách Công viên Tivoli và Quảng trường Tòa thị chính 10 phút đi bộ. Khách sạn cách Ny Carlsberg Glyptotek 1,1 km và cách Phố Strøget 1,5 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> 00:00–11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều không thể bổ sung giường phụ. Chính sách về cũi khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_content', '<ul><li>Cơ sở lưu trú này có 2 lựa chọn cho suất ăn sáng đặt thêm.</li><li>Ẩm thực: Ẩm thực địa phương</li><li>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-10:00 Đang Mở
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_content', '<p><strong>Đặt cọc</strong> Yêu cầu đặt cọc</p><p><strong>Hình thức thu tiền cọc</strong> Khách sẽ thanh toán số tiền cọc cố định là 1.500 DKK (khoảng 5.984.842₫).</p><p><strong>Hình thức thanh toán tiền cọc</strong> Cơ sở lưu trú này chấp nhận thẻ tín dụng</p><p><strong>Hoàn tiền cọc</strong> Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</p>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_content', '<ul><li>Được phép mang theo thú cưng nếu có yêu cầu</li><li>Loại thú cưng được phép mang theo: chó, mèo</li><li>Phí: 200 DKK (khoảng 797.979₫)/thú cưng/đêm</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_title', 'Động vật hỗ trợ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_content', '<ul><li>Được phép mang theo động vật hỗ trợ nếu có yêu cầu</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_title', 'Thanh toán tại khách sạn');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_content', '<ul><li>Tiền mặt</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_title', 'Lưu ý đặt phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744865, 'vi', 'policy_content', '<p><strong>Các tiện nghi có sẵn</strong> Từ ngày 15 tháng 1, lối vào khách sạn sẽ tạm thời được di dời đến Colbjørnsensgade 8 do công trình cải tạo đang diễn ra. Thay đổi này sẽ có hiệu lực trong suốt năm 2026.
