INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'hotel_name', '1 hotel Copenhagen');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'open_year', '1928');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'room_count', '282');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'hotel_address', 'Krystalgade 22, Indre By, 1172 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'description', 'Tọa lạc tại trung tâm Copenhagen, 1 Hotel Copenhagen cách Khu phố Latin và Nhà thờ Đức Mẹ vài bước. Khách sạn sang trọng này cách Torvehallerne 0,4 km và cách Tháp thiên văn Round Tower 1,1 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 23:30</p><p><strong>Trả phòng</strong> 04:00–12:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều có thể bổ sung cũi. Chính sách về giường phụ khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</li><li>Phí giường phụ và cũi chưa được bao gồm trong tổng giá và phải được thanh toán tại khách sạn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-11:00 Đang Mở
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_content', '<p><strong>Đặt cọc</strong> Yêu cầu đặt cọc</p><p><strong>Hình thức thu tiền cọc</strong> Khách sẽ thanh toán số tiền cọc cố định là 2.000 DKK (khoảng 7.979.789₫).</p><p><strong>Hình thức thanh toán tiền cọc</strong> Cơ sở lưu trú này chấp nhận thẻ tín dụng</p><p><strong>Hoàn tiền cọc</strong> Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</p>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (744872, 'vi', 'policy_title', 'Thú cưng');
