INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'hotel_name', 'AC Hotel Bella Sky Copenhagen');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'open_year', '2014');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'room_count', '811');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'hotel_address', 'Martha Christensens Vej 5, Amager Vest, 2300 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'description', 'Tọa lạc tại trung tâm Copenhagen, AC Hotel by Marriott Bella Sky Copenhagen cách Sân vận động Royal 3 phút lái xe và cách Phố Strøget 7 phút lái xe. Khách sạn golf này cách Quảng trường Tòa thị chính 5,5 km và cách Công viên Tivoli 5,6 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> Trước 12:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Ẩm thực: Đại lục</li><li>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-10:30 Đang Mở
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_content', '<p><strong>Đặt cọc</strong> Yêu cầu đặt cọc</p><p><strong>Hình thức thu tiền cọc</strong> Khách sẽ thanh toán số tiền cọc cố định là 250 DKK (khoảng 997.474₫).</p><p><strong>Hình thức thanh toán tiền cọc</strong> Cơ sở lưu trú này chấp nhận thẻ tín dụng</p><p><strong>Hoàn tiền cọc</strong> Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</p>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_content', '<ul><li>Được phép mang theo thú cưng nếu có yêu cầu</li><li>Loại thú cưng được phép mang theo: chó, mèo</li><li>Phí: 300 DKK (khoảng 1.196.968₫)/phòng/ngày</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_title', 'Động vật hỗ trợ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_content', '<ul><li>Được phép mang theo động vật hỗ trợ nếu có yêu cầu</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_title', 'Thanh toán tại khách sạn');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (1863116, 'vi', 'policy_content', '<ul><li>Tiền mặt</li></ul>');
