INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'hotel_name', 'Wakeup Copenhagen - Borgergade');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'local_name', 'Wakeup Copenhagen Borgergade');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'open_year', '2014');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'room_count', '770');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'hotel_address', 'Borgergade 9, Indre By, 1300 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'description', 'Wakeup Copenhagen Borgergade ở trung tâm Copenhagen, chỉ cách Phố Strøget 5 phút đi bộ và cách Khu Nyhavn 6 phút đi bộ. Khách sạn này cách Công viên Tivoli 2,3 km và cách Quảng trường Tòa thị chính 1,9 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 15:00</p><p><strong>Trả phòng</strong> Trước 11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều có thể bổ sung cũi, nhưng không thể bổ sung giường phụ.</li><li>Phí giường phụ và cũi chưa được bao gồm trong tổng giá và phải được thanh toán tại khách sạn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:00 Đang Mở</li><li>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_content', '<ul><li>Không được phép mang theo thú cưng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_title', 'Thanh toán tại khách sạn');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2198090, 'vi', 'policy_content', '<ul><li>Tiền mặt</li></ul>');
