INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'open_year', '1935');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'room_count', '85');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'hotel_address', 'Vandkunsten 5, Indre By, 1467 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'description', 'Copenhagen Downtown Hostel ở trung tâm Copenhagen, cách Quảng trường Tòa thị chính và Phố Strøget 5 phút đi bộ. Hostel này cách Công viên Tivoli 0,7 km và cách Khu Nyhavn 1,1 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> 06:00–10:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_content', '<ul><li>Cơ sở lưu trú này không nhận khách lưu trú là trẻ em</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Giờ mở cửa: [Thứ 2 - CN] 07:30-10:30 Đang Mở</li><li>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_content', '<p><strong>Đặt cọc</strong> Chỗ nghỉ không yêu cầu đặt cọc</p>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_content', '<ul><li>Không được phép mang theo thú cưng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_title', 'Thanh toán tại khách sạn');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_content', '<ul><li>Tiền mặt</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_title', 'Lưu ý đặt phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2546719, 'vi', 'policy_content', '<p><strong>Không cho phép trẻ em</strong> Không cho phép trẻ em ở khách sạn này.</p><p><strong>Các quy định khác</strong> Chỉ những khách đã đăng ký mới được phép vào phòng nghỉ.</p>');
