INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'description', 'Tọa lạc tại Frederiksberg C, Frederiksberg, Boutique Hotel Hans cách Trung tâm Hội nghị - Triển lãm Forum Copenhagen và Nghĩa trang Assistens 15 phút đi bộ. Khách sạn boutique này cách Công viên Tivoli 1,6 km và cách Torvehallerne 1,6 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> Trước 11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Chủ nhà hoặc nhân viên sẽ đón tiếp bạn khi bạn đến nơi</li><li>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Ẩm thực: Tây phương, Đại lục, Không Gluten, Halal, Thuần chay, Chay, Ẩm thực địa phương</li><li>Giờ mở cửa: [Thứ 2 - Thứ 6] 07:00-10:00 Đang Mở
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_content', '<ul><li>Không được phép mang theo thú cưng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_title', 'Động vật hỗ trợ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_content', '<ul><li>Được phép mang theo động vật hỗ trợ nếu có yêu cầu</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564758, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
