INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'hotel_address', 'Helgolandsgade 15, Vesterbro/Kongens Enghave, 1653 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'description', 'Khám phá tất cả những gì Vesterbro/Kongens Enghave mang lại trong thời gian bạn lưu trú tại Annex Copenhagen.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 14:00</p><p><strong>Trả phòng</strong> 06:00–11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Quầy tự nhận phòng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_content', '<ul><li>Không có bữa sáng.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_content', '<ul><li>Không được phép mang theo thú cưng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2564766, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
