INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'hotel_address', 'Banegårdspladsen 4, Vesterbro/Kongens Enghave, 1570 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'description', 'Tọa lạc tại trung tâm Copenhagen, Hotel Astoria, BW Signature Collection cách Công viên Tivoli 3 phút đi bộ và cách Quảng trường Tòa thị chính 7 minutes phút đi bộ. Khách sạn cách Bảo tàng Quốc gia Đan Mạch 1,1 km và cách Phố Strøget 1,3 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 15:00</p><p><strong>Trả phòng</strong> 03:00–12:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'policy_content', '<ul><li>Ẩm thực: Tây phương</li><li>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-10:00 Đang Mở
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (2576120, 'vi', 'policy_content', '<ul><li>Được phép mang theo thú cưng</li><li>Phí: 400 DKK (khoảng 1.595.958₫)/phòng/lần lưu trú</li></ul>');
