INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'open_year', '1906');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'room_count', '66');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'hotel_address', 'Vesterbrogade 34, Vesterbro/Kongens Enghave, 1620 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'description', 'Tọa lạc tại trung tâm Copenhagen, Savoy Hotel chỉ cách Công viên Tivoli 8 phút đi bộ và Quảng trường Tòa thị chính 11 phút đi bộ. Khách sạn cách Cung điện Christiansborg 1,5 km và cách Phố Strøget 1,6 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 15:00</p><p><strong>Trả phòng</strong> 00:00–11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Tự nhận phòng: Liên lạc với chỗ nghỉ để được hướng dẫn cách lấy thẻ/chìa khóa</li><li>Chỗ nghỉ sẽ cung cấp thông tin nhận phòng sau khi bạn đặt đơn</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_content', '<ul><li>Lựa chọn: Đồ ăn đóng hộp/gói</li><li>Ẩm thực: Đại lục</li><li>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_content', '<p><strong>Đặt cọc</strong> Chỗ nghỉ không yêu cầu đặt cọc</p>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_content', '<ul><li>Không được phép mang theo thú cưng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_title', 'Động vật hỗ trợ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_content', '<ul><li>Được phép mang theo động vật hỗ trợ nếu có yêu cầu</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_title', 'Thanh toán tại khách sạn');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (3064270, 'vi', 'policy_content', '<ul><li>Thanh toán tại khách sạn</li></ul>');
