INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'description', 'Khi lưu trú tại a&o Copenhagen Nørrebro, bạn sẽ có vị trí hoàn hảo để khám phá Norrebro.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 15:00</p><p><strong>Trả phòng</strong> Trước 10:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Nhận phòng qua ứng dụng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Ẩm thực: Đại lục, Không Gluten, Halal, Thuần chay, Chay</li><li>Giờ mở cửa: [Thứ 7 - CN] 07:00-11:00 Đang Mở
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_content', '<p><strong>Đặt cọc</strong> Chỗ nghỉ không yêu cầu đặt cọc</p>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_content', '<ul><li>Được phép mang theo thú cưng nếu có yêu cầu</li><li>Loại thú cưng được phép mang theo: chó</li><li>Phí: 115 DKK (khoảng 458.838₫)/thú cưng/ngày</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_title', 'Thời gian yên tĩnh');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_content', '<ul><li>Khách được yêu cầu giữ yên tĩnh từ 22:00 đến 06:00</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_title', 'Thanh toán tại khách sạn');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_content', '<ul><li>Thanh toán tại khách sạn</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_title', 'Lưu ý đặt phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (7021883, 'vi', 'policy_content', '<p><strong>Giới hạn về nhận phòng</strong> Xin lưu ý rằng vật nuôi chỉ được phép ở trong các phòng riêng như phòng đơn và phòng đôi và phải trả thêm phí. Vật nuôi không được phép ở trong phòng ngủ tập thể. Khăn tắm không được bao gồm trong giá phòng của phòng ngủ tập thể. Khách có thể thuê khăn tắm tại chỗ nghỉ với một khoản phụ phí hoặc tự mang theo. Bộ khăn trải giường cho giường tầng được cung cấp miễn phí và để tự đắp.</p>');
