INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'hotel_name', 'Steel House Copenhagen');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'open_year', '2016');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'room_count', '253');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'hotel_address', 'Herholdtsgade 6, Indre By, 1605 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'description', 'Tọa lạc tại trung tâm Copenhagen, Steel House Copenhagen - Hostel, cách Công viên Tivoli và Quảng trường Tòa thị chính 10 phút đi bộ. Hostel phù hợp cho khách gia đình này cách Vườn Bách thảo 1,4 km và cách Phố Strøget 1,4 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> Trước 11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Giờ mở cửa: [Thứ 2 - CN] 06:30-11:00 Đang Mở</li><li>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_content', '<p><strong>Đặt cọc</strong> Chỗ nghỉ không yêu cầu đặt cọc</p>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_content', '<ul><li>Không được phép mang theo thú cưng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (9977383, 'vi', 'policy_title', 'Thanh toán tại khách sạn');
