INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'hotel_name', 'Cabinn Copenhagen');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'local_name', 'CABINN Copenhagen');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'open_year', '2019');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'room_count', '1202');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'hotel_address', 'Arni Magnussons Gade 1, Vesterbro/Kongens Enghave, 1577 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'description', 'CABINN Copenhagen ở trung tâm Copenhagen, cách Công viên Tivoli và Quảng trường Tòa thị chính 5 phút lái xe. Khách sạn này cách Khu Nyhavn 2,7 km và cách Phố Strøget 1,8 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> Trước 11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_content', '<ul><li>Ẩm thực: Đại lục</li><li>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-10:00 Đang Mở
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_content', '<p><strong>Đặt cọc</strong> Chỗ nghỉ không yêu cầu đặt cọc</p>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_content', '<ul><li>Không được phép mang theo thú cưng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_title', 'Thanh toán tại khách sạn');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_content', '<ul><li>Tiền mặt</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_title', 'Lưu ý đặt phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (36649443, 'vi', 'policy_content', '<p><strong>Các tiện nghi có sẵn</strong> Xin lưu ý rằng phòng chỉ được dọn dẹp 3 ngày một lần đối với phòng thường và 7 ngày một lần đối với căn hộ.</p>');
