INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'hotel_name', 'Urban Camper Hostel & Bar');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'open_year', '2019');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'room_count', '49');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'hotel_address', 'Lygten 2C, Bispebjerg, 2400 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'description', 'Tọa lạc tại Nordvest, Copenhagen, Urban Camper Hostel cách Phố Jægersborg và Nhà thờ Grundtvig 5 phút lái xe. Hostel cách Nghĩa trang Assistens 2 km và cách Hồ Peblinge 3,3 km.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> Trước 11:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Chủ nhà hoặc nhân viên sẽ đón tiếp bạn khi bạn đến nơi</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_content', '<ul><li>Cơ sở lưu trú này không nhận khách lưu trú là trẻ em</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_content', '<ul><li>Ẩm thực: Đại lục</li><li>Giờ mở cửa: [Thứ 2 - CN] 07:00-10:00 Đang Mở</li><li>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_content', '<ul><li>Không được phép mang theo thú cưng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_title', 'Động vật hỗ trợ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_content', '<ul><li>Được phép mang theo động vật hỗ trợ</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_title', 'Tiệc tùng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_content', '<ul><li>Không được phép tổ chức tiệc và các hoạt động</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_title', 'Thanh toán tại khách sạn');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_content', '<ul><li>Thanh toán tại khách sạn</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_title', 'Lưu ý đặt phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (48162461, 'vi', 'policy_content', '<p><strong>Không cho phép trẻ em</strong> Không cho phép trẻ em ở khách sạn này.</p><p><strong>Phí phòng</strong> Xin lưu ý rằng những mục sau đây có thể phải trả phí tại chỗ, bạn có thể liên hệ với khách sạn để biết số tiền cụ thể theo nhu cầu của mình: bữa sáng kiểu lục địa, bãi đậu xe tự phục vụ, bãi đậu xe gần đó.</p>');
