INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'description', 'Khi lưu trú tại a&o Copenhagen Sydhavn, bạn sẽ có vị trí hoàn hảo để khám phá Vesterbro/Kongens Enghave.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> 15:00 – 24:00</p><p><strong>Trả phòng</strong> 06:00–10:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Nhận phòng qua ứng dụng</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_content', '<ul><li>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_content', '<ul><li>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_content', '<ul><li>Lựa chọn: Tự chọn</li><li>Ẩm thực: Đại lục</li><li>Giờ mở cửa: [Thứ 7 - CN] 07:00-11:00 Đang Mở
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_content', '<ul><li>Được phép mang theo thú cưng nếu có yêu cầu</li><li>Loại thú cưng được phép mang theo: chó, mèo</li><li>Phí: 115 DKK (khoảng 458.838₫)/thú cưng/ngày</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_title', 'Động vật hỗ trợ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_content', '<ul><li>Được phép mang theo động vật hỗ trợ nếu có yêu cầu</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_title', 'Giới hạn độ tuổi');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (58407652, 'vi', 'policy_content', '<ul><li>Khách chính nhận phòng phải từ 18 tuổi trở lên.</li></ul>');
