INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (134013415, 'vi', 'description', 'Nice Stay near SGN Airport by Sy''s Home là nơi lý tưởng để thư giãn sau một ngày đi du lịch hoặc làm việc.');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (134013415, 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (134013415, 'vi', 'policy_content', '<p><strong>Nhận phòng</strong> Sau 14:00</p><p><strong>Trả phòng</strong> Trước 12:00</p><ul><li>Giờ làm việc của quầy lễ tân: 24/7</li><li>Để nhận phòng, vui lòng liên lạc với chỗ nghỉ qua email/điện thoại trước một ngày.Đồng thời, vui lòng cung cấp giờ nhận phòng của bạn, giấy tờ chứng minh danh tính</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (134013415, 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (134013415, 'vi', 'policy_content', '<ul><li>Trẻ em 5 tuổi trở lên được chào đón tại khách sạn này.</li><li>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (134013415, 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (134013415, 'vi', 'policy_content', '<ul><li>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</li></ul>');
INSERT INTO splatform_meta.trip_property_translation (property_id, lang, filed, value) VALUES (134013415, 'vi', 'policy_title', 'Bữa sáng');
